import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

// .github/dependabot.yml is generated from the template folders, because
// Dependabot needs each one listed by name: a "/templates/*" glob would also
// pick up folders without a package.json. Every template, vendored ones
// included, gets grouped security updates. A vendored template's package.json
// and lockfile may then differ from upstream in dependency versions until the
// next upstream sync (see upstream-copy.mjs).
//
//   dependabot-config.mjs           exit 1 if dependabot.yml is out of date
//   dependabot-config.mjs --write   regenerate it

export const DEPENDABOT_FILE = '.github/dependabot.yml';

export function renderDependabotConfig(ids) {
  const lines = [
    '# Generated by .github/scripts/dependabot-config.mjs from templates/.',
    '# Do not edit by hand: run `node .github/scripts/dependabot-config.mjs --write`.',
    'version: 2',
    'updates:',
    '  - package-ecosystem: npm',
    '    directories:',
    ...ids.map((id) => `      - "/templates/${id}"`),
    '    schedule:',
    '      interval: daily',
    '    # Version updates off. Security updates stay on and are grouped so',
    '    # one vulnerable package opens one PR across every matching template.',
    '    open-pull-requests-limit: 0',
    '    groups:',
    '      security:',
    '        applies-to: security-updates',
    '        group-by: dependency-name',
    '        patterns:',
    '          - "*"',
    '        update-types:',
    '          - minor',
    '          - patch',
  ];
  return `${lines.join('\n')}\n`;
}

// Template folders with a package.json.
export function templateDirectories(root = '.') {
  return readdirSync(join(root, 'templates'), { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && existsSync(join(root, 'templates', entry.name, 'package.json')))
    .map((entry) => entry.name)
    .sort();
}

function main() {
  const expected = renderDependabotConfig(templateDirectories('.'));
  if (process.argv.includes('--write')) {
    writeFileSync(DEPENDABOT_FILE, expected);
    console.log(`Wrote ${DEPENDABOT_FILE}.`);
    return;
  }
  const actual = existsSync(DEPENDABOT_FILE) ? readFileSync(DEPENDABOT_FILE, 'utf8') : '';
  if (actual !== expected) {
    console.log(`::error file=${DEPENDABOT_FILE}::${DEPENDABOT_FILE} is out of date. Run: node .github/scripts/dependabot-config.mjs --write`);
    process.exit(1);
  }
  console.log(`${DEPENDABOT_FILE} is up to date.`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
